package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.apache.commons.compress.archivers.tar.TarArchiveEntry;
import org.apache.commons.compress.utils.ArchiveUtils;
import org.apache.commons.compress.utils.CountingOutputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarArchiveOutputStream_write_TriageGen2Test {

    private ByteArrayOutputStream out;
    private TarArchiveOutputStream tarOut;
    private static final int BLOCK_SIZE = 512;

    @Before
    public void setUp() throws IOException {
        out = new ByteArrayOutputStream();
        // Using default block size 512
        tarOut = new TarArchiveOutputStream(out, BLOCK_SIZE);
    }









    @Test
    public void testWrite_LargeWrite_WithRemainder() throws IOException {
        // Write 1.5 blocks at once
        int size = (int) (BLOCK_SIZE * 1.5);
        TarArchiveEntry entry = new TarArchiveEntry("test.txt");
        entry.setSize(size);
        tarOut.putArchiveEntry(entry);

        byte[] data = new byte[size];
        tarOut.write(data, 0, size);

        // The first block is written via buffer.writeRecord(wBuf, wOffset)
        // The remaining 0.5 block is stored in assemBuf
        Assert.assertEquals(BLOCK_SIZE, tarOut.getBytesWritten());

        // Complete the last part
        int remaining = size - BLOCK_SIZE;
        tarOut.write(data, BLOCK_SIZE, remaining);

        Assert.assertEquals(size, tarOut.getBytesWritten());
        tarOut.closeArchiveEntry();
    }






}

